  "pou_name": "MotorControl",
  "pou_type": "FUNCTION_BLOCK",
  "declaration": "FUNCTION_BLOCK MotorControl
    VAR_INPUT
        StartBtn : BOOL;
        StopBtn : BOOL;
        EStop : BOOL;
    END_VAR

    VAR_OUTPUT
        Motor : BOOL;
    END_VAR
END_FUNCTION_BLOCK",
  "implementation": "IF EStop THEN
    Motor := FALSE;
ELSIF StopBtn THEN
    Motor := FALSE;
ELSIF StartBtn THEN
    Motor := TRUE;
END_IF;"
}
